    UINT32 scale3D = (size3D - 1) / 255.0f * (1 << SCALE_BITS);
    int size1D_2D = size1D * size2D;
    int x, y;
    ImagingSectionCookie cookie;

    __m128i v_scale1D = _mm_set1_epi32(scale1D);
    __m128i v_scale2D = _mm_set1_epi32(scale2D);
    __m128i v_scale3D = _mm_set1_epi32(scale3D);
    __m128i v_scale_mask = _mm_set1_epi32(SCALE_MASK);
    __m128i v_shift_r = _mm_set1_epi32(SCALE_BITS - SHIFT_BITS);
    __m128i v_one = _mm_set1_epi32(1);

    ImagingSectionEnter(&cookie);
    for (y = 0; y < imOut->ysize; y++) {
        UINT8 *rowIn = (UINT8 *)imIn->image[y];
        char *rowOut = (char *)imOut->image[y];
        x = 0;
        /* Process 4 pixels at a time */
        for (; x + 3 < imOut->xsize; x += 4) {
            /* Load 4 pixels R, G, B values */
            /* Each pixel is 4 bytes: R, G, B, A */
            __m128i pixels = _mm_loadu_si128((__m128i*)&rowIn[x * 4]);

            /* Extract R, G, B channels for 4 pixels */
            /* R: bytes 0,4,8,12  G: bytes 1,5,9,13  B: bytes 2,6,10,14 */
            __m128i r_mask = _mm_setr_epi8(0, -1, -1, -1, 4, -1, -1, -1, 8, -1, -1, -1, 12, -1, -1, -1);
            __m128i g_mask = _mm_setr_epi8(1, -1, -1, -1, 5, -1, -1, -1, 9, -1, -1, -1, 13, -1, -1, -1);
            __m128i b_mask = _mm_setr_epi8(2, -1, -1, -1, 6, -1, -1, -1, 10, -1, -1, -1, 14, -1, -1, -1);

            __m128i r_vals = _mm_shuffle_epi8(pixels, r_mask);
            __m128i g_vals = _mm_shuffle_epi8(pixels, g_mask);
            __m128i b_vals = _mm_shuffle_epi8(pixels, b_mask);

            /* Compute indices */
            __m128i idx1D = _mm_mullo_epi32(r_vals, v_scale1D);
            __m128i idx2D = _mm_mullo_epi32(g_vals, v_scale2D);
            __m128i idx3D = _mm_mullo_epi32(b_vals, v_scale3D);

            /* Compute shifts */
            __m128i shift1D_v = _mm_srli_epi32(_mm_and_si128(idx1D, v_scale_mask), SCALE_BITS - SHIFT_BITS);
            __m128i shift2D_v = _mm_srli_epi32(_mm_and_si128(idx2D, v_scale_mask), SCALE_BITS - SHIFT_BITS);
            __m128i shift3D_v = _mm_srli_epi32(_mm_and_si128(idx3D, v_scale_mask), SCALE_BITS - SHIFT_BITS);

