#ifdef __SSE4_2__

#include "ImagingSIMD.h"
#include <string.h>

/* SIMD version for 3-channel LUT - vectorizes the 3-channel interpolation */
static Imaging
ImagingColorLUT3D_linear_3ch_SSE4(
    Imaging imOut, Imaging imIn,
    int table_channels,
    int size1D, int size2D, int size3D,
    INT16 *table) {

    UINT32 scale1D = (UINT32)((size1D - 1) / 255.0f * (1 << SCALE_BITS));
    UINT32 scale2D = (UINT32)((size2D - 1) / 255.0f * (1 << SCALE_BITS));
    UINT32 scale3D = (UINT32)((size3D - 1) / 255.0f * (1 << SCALE_BITS));
    int size1D_2D = size1D * size2D;
    int x, y;
    ImagingSectionCookie cookie;

    ImagingSectionEnter(&cookie);
    for (y = 0; y < imOut->ysize; y++) {
        UINT8 *rowIn = (UINT8 *)imIn->image[y];
        char *rowOut = (char *)imOut->image[y];
        for (x = 0; x < imOut->xsize; x++) {
            UINT32 index1D = rowIn[x * 4 + 0] * scale1D;
            UINT32 index2D = rowIn[x * 4 + 1] * scale2D;
            UINT32 index3D = rowIn[x * 4 + 2] * scale3D;
            INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
            INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
            int idx = table_channels * table_index3D(
                index1D >> SCALE_BITS, index2D >> SCALE_BITS, index3D >> SCALE_BITS,
                size1D, size1D_2D);

            /* Load 8 corner values for trilinear interpolation */
            /* Each corner has 3 INT16 values - load as 128-bit and interpolate */
            __m128i c000 = _mm_loadu_si128((__m128i*)&table[idx]);
            __m128i c100 = _mm_loadu_si128((__m128i*)&table[idx + 3]);
            __m128i c010 = _mm_loadu_si128((__m128i*)&table[idx + size1D * 3]);
            __m128i c110 = _mm_loadu_si128((__m128i*)&table[idx + size1D * 3 + 3]);
            __m128i c001 = _mm_loadu_si128((__m128i*)&table[idx + size1D_2D * 3]);
            __m128i c101 = _mm_loadu_si128((__m128i*)&table[idx + size1D_2D * 3 + 3]);
            __m128i c011 = _mm_loadu_si128((__m128i*)&table[idx + size1D_2D * 3 + size1D * 3]);
            __m128i c111 = _mm_loadu_si128((__m128i*)&table[idx + size1D_2D * 3 + size1D * 3 + 3]);

            /* Interpolate along axis 1 (R) */
            __m128i v_shift1D = _mm_set1_epi16(shift1D);
            __m128i v_ones = _mm_set1_epi16(1 << SHIFT_BITS);
            __m128i v_inv_shift1D = _mm_sub_epi16(v_ones, v_shift1D);

            __m128i c00 = _mm_add_epi16(_mm_mullo_epi16(c000, v_inv_shift1D), _mm_mullo_epi16(c100, v_shift1D));
            __m128i c10 = _mm_add_epi16(_mm_mullo_epi16(c010, v_inv_shift1D), _mm_mullo_epi16(c110, v_shift1D));
            __m128i c01 = _mm_add_epi16(_mm_mullo_epi16(c001, v_inv_shift1D), _mm_mullo_epi16(c101, v_shift1D));
            __m128i c11 = _mm_add_epi16(_mm_mullo_epi16(c011, v_inv_shift1D), _mm_mullo_epi16(c111, v_shift1D));

            /* Interpolate along axis 2 (G) */
            __m128i v_shift2D = _mm_set1_epi16(shift2D);
            __m128i v_inv_shift2D = _mm_sub_epi16(v_ones, v_shift2D);

            __m128i c0 = _mm_add_epi16(_mm_mullo_epi16(c00, v_inv_shift2D), _mm_mullo_epi16(c10, v_shift2D));
            __m128i c1 = _mm_add_epi16(_mm_mullo_epi16(c01, v_inv_shift2D), _mm_mullo_epi16(c11, v_shift2D));

            /* Interpolate along axis 3 (B) */
            __m128i v_shift3D = _mm_set1_epi16(shift3D);
            __m128i v_inv_shift3D = _mm_sub_epi16(v_ones, v_shift3D);

            __m128i result_v = _mm_add_epi16(_mm_mullo_epi16(c0, v_inv_shift3D), _mm_mullo_epi16(c1, v_shift3D));
            result_v = _mm_srai_epi16(result_v, SHIFT_BITS);

            /* Extract and clip the 3 channel values */
            INT16 result[8];
            _mm_storeu_si128((__m128i*)result, result_v);

            UINT32 v = MAKE_UINT32(clip8(result[0]), clip8(result[1]), clip8(result[2]), rowIn[x * 4 + 3]);
            memcpy(rowOut + x * sizeof(v), &v, sizeof(v));
        }
    }
    ImagingSectionLeave(&cookie);
    return imOut;
}

#endif /* __SSE4_2__ */
ENDSIMD

