            /* Use 32-bit arithmetic to avoid overflow */
            __m128i c000 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i*)&table[idx]));
            __m128i c100 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i*)&table[idx + 3]));
            __m128i c010 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i*)&table[idx + size1D * 3]));
            __m128i c110 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i*)&table[idx + size1D * 3 + 3]));
            __m128i c001 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i*)&table[idx + size1D_2D * 3]));
            __m128i c101 = _mm_cvtepi16_epi32(_mm_loadl_epi64((__m128i*)&table[idx + size1D_2D * 3 + 3]));
