            __m128i v_shift1D = _mm_set1_epi32(shift1D);
            __m128i v_ones = _mm_set1_epi32(1 << SHIFT_BITS);
            __m128i v_inv_shift1D = _mm_sub_epi32(v_ones, v_shift1D);

