/* SIMD clip8: converts from fixed-point to UINT8 with clamping */
static inline __m128i
simd_clip8(__m128i values) {
    /* Add rounding and shift by PRECISION_BITS */
    values = _mm_add_epi32(values, _mm_set1_epi32(PRECISION_ROUNDING));
    values = _mm_srai_epi32(values, PRECISION_BITS);
    /* Pack to 16-bit with signed saturation (clamps to [-32768, 32767]) */
    values = _mm_packs_epi32(values, values);
    /* Pack to 8-bit with unsigned saturation (clamps to [0, 255]) */
    values = _mm_packus_epi16(values, values);
    return values;
}

